SELECT s.Id,s.Title,s.HomePageSectionTypeId,s.WidgetZone,s.DisplayOrder,s.ContentHtml,i.Id AS ItemId,i.Title AS ItemTitle,i.Url,i.PictureId,i.MobilePictureId,i.DisplayOrder AS ItemDisplayOrder FROM HomePageSection s LEFT JOIN HomePageSectionItem i ON i.HomePageSectionId=s.Id AND i.Published=1 AND i.Deleted=0 WHERE s.Deleted=0 AND s.Published=1 AND s.LimitedToIdBrandPage=0 AND s.LimitedToIdTopicPage=0 ORDER BY s.DisplayOrder,i.DisplayOrder
